class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) {
            return null;
        }
        Map<Node, Node> m = new HashMap<>();            // 旧节点 -> 新节点
        Node cur = head;
        while (cur != null) {                           // 第一遍：只造节点
            m.put(cur, new Node(cur.val));
            cur = cur.next;
        }
        cur = head;
        while (cur != null) {                           // 第二遍：连指针
            m.get(cur).next = m.get(cur.next);          // 指向空时 get(null) 也是 null
            m.get(cur).random = m.get(cur.random);
            cur = cur.next;
        }
        return m.get(head);
    }
}

